import os,sys,types,json,hashlib,time
os.environ.update(CUDA_VISIBLE_DEVICES='',PYTHONDONTWRITEBYTECODE='1',OMP_NUM_THREADS='1',MKL_NUM_THREADS='1')
import torch
torch.set_num_threads(1)
SOURCES={'legacy_losses': '"""Frozen CCBP-v1 and two execution-matched controls; no trainable additions."""\nimport torch\nimport torch.nn.functional as F\nGROUPS=((0,3),(3,6),(6,7))\ndef cost(mu,sd,y,scale):\n return sum(((mu[:,:,a:b]-y[:,None,a:b]).square()+sd[:,:,a:b].square()).mean(-1)/scale[g].square() for g,(a,b) in enumerate(GROUPS))\ndef w2(mu,sd,tm,ts,scale):\n return sum(((mu[:,:,a:b]-tm[:,None,a:b]).square()+(sd[:,:,a:b]-ts[:,None,a:b]).square()).mean(-1)/scale[g].square() for g,(a,b) in enumerate(GROUPS))\ndef route(logits,good):\n good=good.detach();allgood=good.all(-1);assert good.any(-1).all()\n # Finite sentinels avoid inf*0 and retain an exact zero for all-good rows.\n hi=logits.masked_fill(~good,-1e9).max(-1).values\n bad=logits.masked_fill(good,-1e9).max(-1).values\n return torch.where(allgood,logits.sum(-1)*0,F.relu(.1+bad-hi))\ndef aux(arm,q,y,teacher,scale):\n mu,sd,logits=q;tm,ts,tl=teacher;ix=torch.arange(len(y),device=y.device)\n winner=logits.detach().argmax(-1);tk=tl.argmax(-1)\n cc=cost(mu,sd,y,scale);selected=cc[ix,winner]\n budget=cost(tm,ts,y,scale)[ix,tk].detach()+.05\n if arm==\'A\':return mu.sum()*0,dict(count=len(y))\n if arm==\'B\':\n  d=w2(mu,sd,tm[ix,tk],ts[ix,tk],scale);value=d[ix,winner];good=F.one_hot(d.detach().argmin(-1),5).bool();empty=torch.zeros(len(y),device=y.device,dtype=torch.bool)\n elif arm==\'C\':\n  value=selected;good=F.one_hot(cc.detach().argmin(-1),5).bool();empty=torch.zeros(len(y),device=y.device,dtype=torch.bool)\n else:\n  assert arm==\'D\';good=cc.detach()<=budget[:,None];empty=~good.any(-1)\n  value=F.relu(selected-budget)+empty.to(selected.dtype)*F.relu(cc.min(-1).values-budget)\n  good=good| (empty[:,None]&F.one_hot(cc.detach().argmin(-1),5).bool())\n rr=route(logits,good);loss=(value+.1*rr).mean()\n return loss,dict(count=len(y),expert_selected_sum=float(selected.detach().sum()),teacher_budget_sum=float(budget.sum()),excess_sum=float(F.relu(selected-budget).detach().sum()),route_sum=float(rr.detach().sum()),empty=int(empty.sum()),all_good=int(good.all(-1).sum()))\n', 'prototype_loss': '"""CCBP-v2 proposal: continuous correction, quality-weighted anchor, cost-sensitive routing.\n\nThis is a locally tested loss prototype, NOT a validated robot-learning method.\nIt does not change the policy architecture, rollout decoder, buffer, or base BC/IFA.\nUse in a NEW experiment directory; do not overwrite the frozen CCBP-v1 experiment.\n\nTraining contract:\n* Call on the same eligible old-task / ALIGN-valid windows as the original auxiliary.\n* Teacher parameters come from the frozen stage-start teacher in eval mode.\n* Estimate teacher_cost_median ONCE per protected task from its valid training replay.\n* Compute the student auxiliary forward in eval mode WITH gradients; preserve and\n  restore module modes/RNG as in the original train.py. Teacher targets are detached.\n* Suggested initial screening total loss retains the original outer coefficients:\n      loss = aligned_bc + 0.1 * ifa + 0.1 * auxiliary\n  Coefficients are an unoptimized initial protocol, not evidence of an optimum.\n* Deployment remains argmax(logits), followed by Normal sampling. Expert actions and\n  teacher_cost_median are NOT required at deployment.\n"""\nfrom __future__ import annotations\n\nimport math\nfrom typing import Literal, Tuple\n\nimport torch\nimport torch.nn.functional as F\nfrom torch import Tensor\n\nGaussianParams = Tuple[Tensor, Tensor, Tensor]\n_GROUPS = ((0, 3), (3, 6), (6, 7))\n\n\ndef _validate(params: GaussianParams, y: Tensor, scales: Tensor) -> None:\n    mu, sd, logits = params\n    if mu.ndim != 3 or mu.shape[-1] != 7 or mu.shape[1] < 2:\n        raise ValueError("Means must have shape [N, K>=2, 7].")\n    if sd.shape != mu.shape or logits.shape != mu.shape[:2]:\n        raise ValueError("Standard deviations / logits do not match means.")\n    if y.shape != (mu.shape[0], 7) or scales.shape != (3,):\n        raise ValueError("Targets must be [N,7] and group scales [3].")\n    if not all(torch.isfinite(t).all().item() for t in (*params, y, scales)):\n        raise ValueError("All inputs must be finite.")\n    if not (sd > 0).all().item() or not (scales > 0).all().item():\n        raise ValueError("Standard deviations and group scales must be positive.")\n    if not all(t.device == mu.device for t in (sd, logits, y, scales)):\n        raise ValueError("Student parameters, targets and scales must share a device.")\n\n\ndef expert_cost(mu: Tensor, sd: Tensor, y: Tensor, scales: Tensor) -> Tensor:\n    """Original normalized expected squared action error; returns [N,K]."""\n    return sum(\n        ((mu[:, :, lo:hi] - y[:, None, lo:hi]).square()\n         + sd[:, :, lo:hi].square()).mean(-1) / scales[g].square()\n        for g, (lo, hi) in enumerate(_GROUPS)\n    )\n\n\ndef behavior_distance(\n    mu: Tensor, sd: Tensor, teacher_mu: Tensor, teacher_sd: Tensor, scales: Tensor\n) -> Tensor:\n    """Grouped diagonal-Gaussian W2-squared to teacher EXECUTED component [N,K]."""\n    return sum(\n        ((mu[:, :, lo:hi] - teacher_mu[:, None, lo:hi]).square()\n         + (sd[:, :, lo:hi] - teacher_sd[:, None, lo:hi]).square()).mean(-1)\n        / scales[g].square()\n        for g, (lo, hi) in enumerate(_GROUPS)\n    )\n\n\n@torch.no_grad()\ndef estimate_teacher_cost_median(\n    teacher: GaussianParams, y: Tensor, scales: Tensor\n) -> float:\n    """Estimate once using ALL valid TRAINING replay for one protected task.\n\n    Only this numerical floor prevents a zero denominator. It is NOT a behavior\n    tolerance or safety threshold. Freeze the returned value for the whole stage.\n    """\n    _validate(teacher, y, scales)\n    if len(y) == 0:\n        raise ValueError("Cannot calibrate from an empty training replay.")\n    mu, sd, logits = teacher\n    winner = logits.argmax(-1)\n    selected = expert_cost(mu, sd, y, scales).gather(1, winner[:, None]).squeeze(1)\n    return float(torch.quantile(selected.double(), 0.5).clamp_min(1e-8))\n\n\ndef regret_route(logits: Tensor, score: Tensor) -> Tensor:\n    """Cost-gap-weighted softplus ranking, one value per window.\n\n    Detached costs prevent logits supervision from changing a component\'s score\n    just to make it easier to rank. No fixed margin or good/bad set is used.\n    This is a SOFT training loss, not an enforced constraint or a success guarantee.\n    """\n    if logits.shape != score.shape or logits.ndim != 2 or logits.shape[1] < 2:\n        raise ValueError("Logits and scores must share shape [N,K>=2].")\n    frozen = score.detach()\n    best_score = frozen.min(-1, keepdim=True).values\n    gap = (frozen - best_score).clamp_min(0)\n    # Resolve exact cost ties by the highest logit, not by a component index.\n    # This mask marks only exact minimizers, NOT a tolerance/acceptable set.\n    minimum_mask = frozen == best_score\n    best_logit = logits.masked_fill(~minimum_mask, -torch.inf).max(-1, keepdim=True).values\n    return (gap * F.softplus(logits - best_logit)).sum(-1) / (logits.shape[1] - 1)\n\n\ndef auxiliary_v2(\n    student: GaussianParams,\n    y: Tensor,\n    teacher: GaussianParams,\n    scales: Tensor,\n    *,\n    teacher_cost_median: float,\n    anchor_strength: float = 1.0,\n    routing_weight: float = 0.1,\n    anchor_mode: Literal["quality", "uniform", "none"] = "quality",\n) -> tuple[Tensor, dict[str, float | int]]:\n    """Return auxiliary scalar and diagnostic aggregates.\n\n    J_m = (c_m + rho*w_i*d_m)/(1 + rho*w_i).\n    w_i = tau/(tau+c_teacher) for quality mode, 1 for uniform, 0 for none.\n    L_i = J_argmax(logits) + beta * regret_route(logits, J).\n\n    At rho=1, the expert term has coefficient >=1/2, so there is no cost-budget\n    dead zone. A quality weight is agreement with demonstration, NOT a calibrated\n    estimate of teacher closed-loop correctness. Even a low-weight anchor may\n    oppose some useful deviations. Evaluate against the no-anchor control.\n    """\n    if anchor_mode not in ("quality", "uniform", "none"):\n        raise ValueError("Unsupported anchor mode.")\n    if not math.isfinite(teacher_cost_median) or teacher_cost_median <= 0:\n        raise ValueError("teacher_cost_median must be a frozen positive scalar.")\n    if any(not math.isfinite(v) or v < 0 for v in (anchor_strength, routing_weight)):\n        raise ValueError("Loss coefficients must be finite and nonnegative.")\n    _validate(student, y, scales)\n    _validate(teacher, y, scales)\n    mu, sd, logits = student\n    tm, ts, tl = (v.detach() for v in teacher)\n    if len(y) == 0:\n        return (mu.sum() + sd.sum() + logits.sum()) * 0, {"count": 0}\n    ix = torch.arange(len(y), device=mu.device)\n    tmode = tl.argmax(-1)\n    tmu, tsd = tm[ix, tmode], ts[ix, tmode]\n    teacher_c = expert_cost(tm, ts, y, scales)[ix, tmode].detach()\n    if anchor_mode == "quality":\n        weight = (teacher_cost_median / (teacher_cost_median + teacher_c)).detach()\n    elif anchor_mode == "uniform":\n        weight = torch.ones_like(teacher_c)\n    else:\n        weight = torch.zeros_like(teacher_c)\n    relative_anchor = anchor_strength * weight\n    cc = expert_cost(mu, sd, y, scales)\n    dd = behavior_distance(mu, sd, tmu, tsd, scales)\n    score = (cc + relative_anchor[:, None] * dd) / (1 + relative_anchor[:, None])\n    winner = logits.detach().argmax(-1)\n    selected_score = score[ix, winner]\n    routing = regret_route(logits, score)\n    loss = (selected_score + routing_weight * routing).mean()\n    if not torch.isfinite(loss).item():\n        raise FloatingPointError("CCBP-v2 auxiliary became nonfinite.")\n    with torch.no_grad():\n        selected_cost = cc[ix, winner]\n        regret = selected_score - score.min(-1).values\n        stats = {\n            "count": len(y),\n            "expert_selected_sum": float(selected_cost.sum()),\n            "behavior_distance_selected_sum": float(dd[ix, winner].sum()),\n            "score_selected_sum": float(selected_score.sum()),\n            "routing_loss_sum": float(routing.sum()),\n            "selection_regret_sum": float(regret.sum()),\n            "selection_regret_max": float(regret.max()),\n            "teacher_quality_weight_sum": float(weight.sum()),\n            "effective_anchor_weight_sum": float((relative_anchor / (1 + relative_anchor)).sum()),\n        }\n    return loss, stats\n', 'losses': '"""Fixed B/C controls, N=rho0 and V=rho1; no budget or threshold scan."""\nimport torch\nimport torch.nn.functional as F\nfrom legacy_losses import cost,w2,route\ndef ranking(logits,score):\n s=score.detach();minimum=s.min(-1).values;ties=s==minimum[:,None]\n # Exact uploaded prototype tie semantics; highest-logit minimum.\n zref=logits.masked_fill(~ties,-torch.inf).max(-1).values\n gap=s-minimum[:,None]\n return (gap*F.softplus(logits-zref[:,None])).sum(-1)/(logits.shape[-1]-1)\ndef aux(arm,q,y,teacher,scale,weight):\n mu,sd,z=q;tm,ts,tz=(t.detach() for t in teacher);ix=torch.arange(len(y),device=y.device)\n k=z.detach().argmax(-1);tk=tz.argmax(-1);c=cost(mu,sd,y,scale)\n distance=w2(mu,sd,tm[ix,tk],ts[ix,tk],scale)\n if arm==\'B\':\n  score=distance;ex=score[ix,k];rr=route(z,F.one_hot(distance.detach().argmin(-1),5).bool())\n elif arm==\'C\':\n  score=c;ex=score[ix,k];rr=route(z,F.one_hot(c.detach().argmin(-1),5).bool())\n else:\n  assert arm in \'NV\';w=weight.detach() if arm==\'V\' else torch.zeros_like(weight)\n  score=(c+w[:,None]*distance)/(1+w[:,None]);ex=score[ix,k];rr=ranking(z,score)\n loss=(ex+.1*rr).mean()\n stats=dict(count=len(y),expert_selected_sum=float(c[ix,k].detach().sum()),anchor_selected_sum=float(distance[ix,k].detach().sum()),score_selected_sum=float(score[ix,k].detach().sum()),score_min_sum=float(score.detach().min(-1).values.sum()),route_sum=float(rr.detach().sum()),regret_sum=float((score[ix,k]-score.min(-1).values).detach().sum()),weight_sum=float(weight.detach().sum()) if arm==\'V\' else 0.)\n return loss,stats,ex.mean(),rr.mean()\n', 'synthetic_checks': '"""Numerical/gradient admission; synthetic CPU tensors, zero optimizer/environment calls."""\nimport torch\nfrom losses import aux,ranking,cost\nfrom prototype_loss import auxiliary_v2,estimate_teacher_cost_median\nfrom legacy_losses import aux as old_aux\ndef run():\n torch.manual_seed(20261024);scale=torch.tensor([.46725568,.1,1.]);y=torch.randn(3,7)\n mu=torch.randn(3,5,7,requires_grad=True);sd=torch.full_like(mu,.2,requires_grad=True);z=torch.randn(3,5,requires_grad=True)\n teacher=(torch.randn_like(mu,requires_grad=True),torch.ones_like(sd,requires_grad=True),torch.randn_like(z,requires_grad=True));w=torch.tensor([.1,.5,.9])\n for arm in \'BC\':\n  new=aux(arm,(mu,sd,z),y,teacher,scale,w)[0];old=old_aux(arm,(mu,sd,z),y,teacher,scale)[0];assert torch.equal(new,old)\n  gn=torch.autograd.grad(new,(mu,sd,z),retain_graph=True);go=torch.autograd.grad(old,(mu,sd,z),retain_graph=True);assert all(torch.equal(a,b) for a,b in zip(gn,go))\n for arm in \'NV\':\n  loss=aux(arm,(mu,sd,z),y,teacher,scale,w)[0];g=torch.autograd.grad(loss,(mu,sd,z,*teacher),allow_unused=True,retain_graph=True)\n  assert all(t is not None and torch.isfinite(t).all() for t in g[:3]) and all(t is None for t in g[3:])\n tau=estimate_teacher_cost_median(teacher,y,scale);ct=cost(teacher[0],teacher[1],y,scale).gather(1,teacher[2].argmax(-1)[:,None]).squeeze(1).detach();ww=tau/(tau+ct)\n for arm,mode in [(\'N\',\'none\'),(\'V\',\'quality\')]:\n  got=aux(arm,(mu,sd,z),y,teacher,scale,ww)[0];expected=auxiliary_v2((mu,sd,z),y,teacher,scale,teacher_cost_median=tau,anchor_mode=mode)[0];assert torch.equal(got,expected)\n  gg=torch.autograd.grad(got,(mu,sd,z),retain_graph=True);ge=torch.autograd.grad(expected,(mu,sd,z),retain_graph=True);assert all(torch.equal(a,b) for a,b in zip(gg,ge))\n # Low expert error still supplies execution regression gradients.\n a=torch.full((1,5,7),.001,requires_grad=True);s=torch.full_like(a,.001,requires_grad=True);l=torch.tensor([[2.,0.,-1.,-2.,-3.]],requires_grad=True)\n t=(torch.zeros_like(a),torch.full_like(s,.001),l.detach());zero=torch.zeros(1,7)\n ex=aux(\'V\',(a,s,l),zero,t,torch.ones(3),torch.ones(1)*.5)[2]\n assert torch.autograd.grad(ex,a)[0].abs().sum()>0\n # Larger fixed score gap => strictly larger routing correction at identical logits.\n zg=torch.zeros(1,5,requires_grad=True);small=torch.tensor([[0.,1.,0.,0.,0.]]);big=small*4\n gs=torch.autograd.grad(ranking(zg,small).sum(),zg,retain_graph=True)[0];gb=torch.autograd.grad(ranking(zg,big).sum(),zg)[0];assert torch.allclose(gb,4*gs)\n # Cost ties choose the highest logit, matching the submitted prototype.\n score=torch.tensor([[0.,0.,2.,3.,4.]],requires_grad=True);zz=torch.tensor([[.7,.8,1.,-.1,.3]],requires_grad=True);perm=torch.tensor([4,1,3,0,2])\n r=ranking(zz,score).sum();g=torch.autograd.grad(r,(zz,score),allow_unused=True);assert g[1] is None\n zp=zz.detach()[:,perm].requires_grad_();rp=ranking(zp,score.detach()[:,perm]).sum();gp=torch.autograd.grad(rp,zp)[0]\n assert torch.allclose(r,rp) and torch.allclose(g[0][:,perm],gp)\n q=(mu,sd,z);permuted=tuple(t[:,perm] for t in q);tp=tuple(t[:,perm] for t in teacher)\n for arm in \'NV\':assert torch.allclose(aux(arm,q,y,teacher,scale,w)[0],aux(arm,permuted,y,tp,scale,w)[0],atol=1e-5,rtol=1e-6)\n assert ranking(torch.zeros(1,5),torch.ones(1,5)).item()==0\n return dict(status=\'PASS\',uploaded_prototype_loss_gradient_exact=True,control_BC_loss_gradient_exact=True,teacher_no_grad=True,low_cost_execution_gradient=True,cost_gap_routing_gradient=True,minimum_tie_and_permutation=True,optimizer_updates=0,environments=0)\n'}
for n,s in SOURCES.items():
 m=types.ModuleType(n);sys.modules[n]=m;exec(compile(s,n,'exec'),m.__dict__)
tic=time.time();result=sys.modules['synthetic_checks'].run()
print(json.dumps(dict(status='PASS_LOCAL_SOURCE_CPU_ADMISSION',results=result,source_sha256={n:hashlib.sha256(s.encode()).hexdigest() for n,s in SOURCES.items()},seconds=time.time()-tic,server_writes=0,cuda_calls=0,observed=time.time())))
